dialect.statement:

UPDATE {table}
SET status = 'DONE', result = ?, finished_at = CURRENT_TIMESTAMP
WHERE scope = ? AND idem_key = ? AND status = 'PROCESSING' AND expire_at = ?


UPDATE {table}
SET status = 'FAILED', error = ?, finished_at = CURRENT_TIMESTAMP
WHERE scope = ? AND idem_key = ? AND status = 'PROCESSING' AND expire_at = ?
